# The cast: one `an character` command per line, run from the project root.
# Mara: tall, hair in a bun, plum coat. A little guarded.
an character new mara --offline --build tall --hair-style bun --hair-length long --palette "skin=#c08a5a,hair=#2b1d14,clothing=#7a3b69,leg=#2e2a3a" --mouth-variants happy,sad --voice-ref mara_voice
# Teo: short and round, red cap, mustard jacket. Relentlessly cheerful.
an character new teo --offline --build squat --head-scale 1.2 --hat cap --hair-style curly --palette "skin=#f1c9a5,hair=#5a3a22,clothing=#d9a62e,accessory=#c0392b,leg=#3a4a6a" --mouth-variants happy,sad --voice-ref teo_voice
